//! rlibc-x2: A minimal libc implementation for Rust std applications
//!
//! This library provides libc functionality for applications that want to use
//! Rust's standard library while avoiding glibc. It implements the minimum set
//! of C library functions needed to support Rust std.

#![no_std]
#![allow(internal_features)]
#![feature(lang_items)]

pub mod errno;
pub mod io;
pub mod memory;
pub mod process;
pub mod signal;
pub mod syscall;
pub mod thread;

/// Macro for creating stub functions that print a message and exit
///
/// Usage: stub!(function_name(arg1: Type1, arg2: Type2) -> ReturnType)
#[macro_export]
macro_rules! stub {
    ($name:ident($($arg:ident: $type:ty),*) -> $ret:ty) => {
        #[unsafe(no_mangle)]
        pub extern "C" fn $name($(_: $type),*) -> $ret {
            // Print stub message
            let msg = concat!("STUB: ", stringify!($name), "\n");
            unsafe {
                $crate::syscall::syscall3(
                    $crate::syscall::SYS_WRITE,
                    2,  // stderr
                    msg.as_ptr() as usize,
                    msg.len(),
                );
                $crate::process::exit(99);
            }
        }
    };
    ($name:ident($($arg:ident: $type:ty),*)) => {
        stub!($name($($arg: $type),*) -> ());
    };
}

// Stubs for functions we haven't implemented yet
stub!(getenv(name: *const i8) -> *mut i8);

// Language items required for no_std with panic = "abort"
#[lang = "eh_personality"]
extern "C" fn eh_personality() {}

#[panic_handler]
fn panic(_info: &core::panic::PanicInfo) -> ! {
    unsafe { process::exit(1) }
}
