//! Process startup and termination

use crate::syscall::{syscall1, SYS_EXIT};
use crate::thread::init_tls;

/// Program entry point - called by the kernel
#[unsafe(no_mangle)]
pub unsafe extern "C" fn _start() -> ! {
    // Get argc, argv, envp from the stack
    // On x86_64 Linux, the stack layout at _start is:
    // rsp -> argc
    // rsp+8 -> argv[0]
    // ...
    // rsp+8*(argc+1) -> NULL
    // rsp+8*(argc+2) -> envp[0]
    // ...
    // NULL

    let argc: i32;
    let argv: *const *const u8;
    let envp: *const *const u8;

    core::arch::asm!(
        "mov {argc:e}, [rsp]",
        "lea {argv}, [rsp + 8]",
        argc = out(reg) argc,
        argv = out(reg) argv,
    );

    // Calculate envp: argv + (argc + 1) * 8
    envp = argv.add((argc as usize) + 1);

    // Initialize TLS before calling main
    init_tls();

    // Call __libc_start_main which will call Rust's main
    __libc_start_main(main, argc, argv, envp);
}

// External reference to Rust's generated main function
extern "C" {
    fn main(argc: i32, argv: *const *const u8) -> i32;
}

/// libc start main - initializes the C runtime and calls main
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __libc_start_main(
    main_fn: unsafe extern "C" fn(i32, *const *const u8) -> i32,
    argc: i32,
    argv: *const *const u8,
    _envp: *const *const u8,
) -> ! {
    let ret = main_fn(argc, argv);
    exit(ret);
}

/// Exit the process
#[unsafe(no_mangle)]
pub unsafe extern "C" fn exit(code: i32) -> ! {
    syscall1(SYS_EXIT, code as usize);
    core::hint::unreachable_unchecked()
}

/// Abort the process
#[unsafe(no_mangle)]
pub unsafe extern "C" fn abort() -> ! {
    exit(134) // 128 + SIGABRT(6)
}
