//! Memory allocation and manipulation functions

use crate::syscall::{syscall1, SYS_BRK};
use core::ffi::c_void;

// Simple bump allocator state
static mut HEAP_START: usize = 0;
static mut HEAP_END: usize = 0;
static mut HEAP_CURRENT: usize = 0;

/// Initialize the heap using brk
unsafe fn init_heap() {
    if HEAP_START == 0 {
        // Get current program break
        HEAP_START = syscall1(SYS_BRK, 0);
        HEAP_CURRENT = HEAP_START;
        HEAP_END = HEAP_START;
    }
}

/// Extend the heap by the given amount
unsafe fn extend_heap(size: usize) -> bool {
    let new_end = HEAP_END + size;
    let result = syscall1(SYS_BRK, new_end);
    if result == new_end {
        HEAP_END = new_end;
        true
    } else {
        false
    }
}

/// Allocate memory
#[unsafe(no_mangle)]
pub unsafe extern "C" fn malloc(size: usize) -> *mut c_void {
    if size == 0 {
        return core::ptr::null_mut();
    }

    init_heap();

    // Align to 16 bytes
    let aligned_size = (size + 15) & !15;

    // Check if we need to extend the heap
    if HEAP_CURRENT + aligned_size > HEAP_END {
        let needed = HEAP_CURRENT + aligned_size - HEAP_END;
        // Extend by at least 4KB at a time
        let extend_size = if needed < 4096 { 4096 } else { needed };
        if !extend_heap(extend_size) {
            return core::ptr::null_mut();
        }
    }

    let ptr = HEAP_CURRENT as *mut c_void;
    HEAP_CURRENT += aligned_size;
    ptr
}

/// Allocate zeroed memory
#[unsafe(no_mangle)]
pub unsafe extern "C" fn calloc(nmemb: usize, size: usize) -> *mut c_void {
    let total = nmemb.saturating_mul(size);
    let ptr = malloc(total);
    if !ptr.is_null() {
        memset(ptr, 0, total);
    }
    ptr
}

/// Reallocate memory
#[unsafe(no_mangle)]
pub unsafe extern "C" fn realloc(ptr: *mut c_void, size: usize) -> *mut c_void {
    if ptr.is_null() {
        return malloc(size);
    }
    if size == 0 {
        free(ptr);
        return core::ptr::null_mut();
    }

    // Simple implementation: always allocate new memory and copy
    // We don't track allocation sizes, so we copy 'size' bytes
    // This is safe because we're a bump allocator - old memory stays valid
    let new_ptr = malloc(size);
    if !new_ptr.is_null() {
        // Copy the old data - we copy 'size' bytes which may be more than
        // the original allocation, but since we never reuse memory, reading
        // past the original allocation just reads old heap data
        memcpy(new_ptr, ptr, size);
    }
    new_ptr
}

/// Free memory (no-op in bump allocator)
#[unsafe(no_mangle)]
pub unsafe extern "C" fn free(_ptr: *mut c_void) {
    // Bump allocator: we don't actually free memory
}

/// Allocate aligned memory
#[unsafe(no_mangle)]
pub unsafe extern "C" fn posix_memalign(
    memptr: *mut *mut c_void,
    alignment: usize,
    size: usize,
) -> i32 {
    // Alignment must be a power of 2 and a multiple of sizeof(void*)
    if alignment == 0 || (alignment & (alignment - 1)) != 0 || alignment % 8 != 0 {
        return 22; // EINVAL
    }

    if size == 0 {
        *memptr = core::ptr::null_mut();
        return 0;
    }

    init_heap();

    // Calculate aligned position
    let aligned_current = (HEAP_CURRENT + alignment - 1) & !(alignment - 1);
    let aligned_size = (size + 15) & !15;

    // Check if we need to extend the heap
    if aligned_current + aligned_size > HEAP_END {
        let needed = aligned_current + aligned_size - HEAP_END;
        let extend_size = if needed < 4096 { 4096 } else { needed };
        if !extend_heap(extend_size) {
            return 12; // ENOMEM
        }
    }

    let ptr = aligned_current as *mut c_void;
    HEAP_CURRENT = aligned_current + aligned_size;
    *memptr = ptr;
    0
}

/// Copy memory
#[unsafe(no_mangle)]
pub unsafe extern "C" fn memcpy(dest: *mut c_void, src: *const c_void, n: usize) -> *mut c_void {
    let d = dest as *mut u8;
    let s = src as *const u8;
    for i in 0..n {
        *d.add(i) = *s.add(i);
    }
    dest
}

/// Set memory
#[unsafe(no_mangle)]
pub unsafe extern "C" fn memset(dest: *mut c_void, c: i32, n: usize) -> *mut c_void {
    let d = dest as *mut u8;
    let byte = c as u8;
    for i in 0..n {
        *d.add(i) = byte;
    }
    dest
}

/// Move memory (handles overlapping regions)
#[unsafe(no_mangle)]
pub unsafe extern "C" fn memmove(dest: *mut c_void, src: *const c_void, n: usize) -> *mut c_void {
    let d = dest as *mut u8;
    let s = src as *const u8;

    if (d as usize) < (s as usize) {
        // Copy forward
        for i in 0..n {
            *d.add(i) = *s.add(i);
        }
    } else {
        // Copy backward
        for i in (0..n).rev() {
            *d.add(i) = *s.add(i);
        }
    }
    dest
}

/// Compare memory
#[unsafe(no_mangle)]
pub unsafe extern "C" fn memcmp(s1: *const c_void, s2: *const c_void, n: usize) -> i32 {
    let p1 = s1 as *const u8;
    let p2 = s2 as *const u8;

    for i in 0..n {
        let a = *p1.add(i);
        let b = *p2.add(i);
        if a != b {
            return (a as i32) - (b as i32);
        }
    }
    0
}
