//! Thread and TLS support

use crate::memory::malloc;
use crate::stub;
use crate::syscall::{syscall2, SYS_ARCH_PRCTL};
use core::ffi::c_void;

// ARCH_SET_FS constant for x86_64
const ARCH_SET_FS: usize = 0x1002;

// Size of TLS area - needs to be large enough for Rust's thread-local storage
const TLS_SIZE: usize = 4096;

/// Initialize thread-local storage
pub unsafe fn init_tls() {
    // Allocate TLS area
    let tls_area = malloc(TLS_SIZE);
    if tls_area.is_null() {
        return;
    }

    // Zero the TLS area
    crate::memory::memset(tls_area, 0, TLS_SIZE);

    // Set FS register to point to TLS area
    // The TLS pointer should point to itself for the pthread self-pointer
    let tls_ptr = tls_area as usize;
    *(tls_area as *mut usize) = tls_ptr;

    syscall2(SYS_ARCH_PRCTL, ARCH_SET_FS, tls_ptr);
}

