//! errno support

use core::ffi::c_void;

// Thread-local errno storage
// For now, we use a simple static since we're single-threaded
static mut ERRNO: i32 = 0;

/// Get pointer to errno
#[unsafe(no_mangle)]
pub unsafe extern "C" fn __errno_location() -> *mut i32 {
    &raw mut ERRNO
}

/// Get string length
#[unsafe(no_mangle)]
pub unsafe extern "C" fn strlen(s: *const i8) -> usize {
    let mut len = 0;
    while *s.add(len) != 0 {
        len += 1;
    }
    len
}

/// Compare strings
#[unsafe(no_mangle)]
pub unsafe extern "C" fn strcmp(s1: *const i8, s2: *const i8) -> i32 {
    let mut i = 0;
    loop {
        let c1 = *s1.add(i) as u8;
        let c2 = *s2.add(i) as u8;
        if c1 != c2 {
            return (c1 as i32) - (c2 as i32);
        }
        if c1 == 0 {
            return 0;
        }
        i += 1;
    }
}

/// Copy string
#[unsafe(no_mangle)]
pub unsafe extern "C" fn strcpy(dest: *mut i8, src: *const i8) -> *mut i8 {
    let mut i = 0;
    loop {
        let c = *src.add(i);
        *dest.add(i) = c;
        if c == 0 {
            break;
        }
        i += 1;
    }
    dest
}

/// Locate character in string
#[unsafe(no_mangle)]
pub unsafe extern "C" fn strchr(s: *const i8, c: i32) -> *mut i8 {
    let c = c as i8;
    let mut i = 0;
    loop {
        let ch = *s.add(i);
        if ch == c {
            return s.add(i) as *mut i8;
        }
        if ch == 0 {
            return core::ptr::null_mut();
        }
        i += 1;
    }
}

