/// The actual entry point called by the kernel.
/// This is defined in assembly to avoid any Rust preamble.
#[naked]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn _start() -> ! {
    core::arch::naked_asm!(
        // Clear frame pointer for clean stack traces
        "xor rbp, rbp",
        // First argument: argc (at top of stack)
        "mov rdi, [rsp]",
        // Second argument: argv (pointer to first arg)
        "lea rsi, [rsp + 8]",
        // Align stack to 16 bytes (required by System V ABI)
        "and rsp, -16",
        // Jump to Rust entry point (tail call)
        "jmp {start_rust}",
        start_rust = sym _start_rust
    )
}

