/// * `size` - Number of bytes to allocate
///
/// # Returns
///
/// Pointer to allocated memory, or null pointer if allocation failed
///
/// # Safety
///
/// The returned pointer is valid until the process exits. Memory is never freed.
pub unsafe fn malloc(size: usize) -> *mut u8 {
    // Align size to 8 bytes
    let aligned_size = (size + 7) & !7;

    // Initialize heap if this is the first allocation
    if HEAP_START == 0 {
        HEAP_START = syscall1(syscall_nums::SYS_BRK, 0);
        HEAP_CURRENT = HEAP_START;
    }

    let ptr = HEAP_CURRENT;
    let new_current = ptr + aligned_size;

    // Extend the heap
    let result = syscall1(syscall_nums::SYS_BRK, new_current);
    if result < new_current {
        // Allocation failed
        return core::ptr::null_mut();
    }

    HEAP_CURRENT = new_current;
    ptr as *mut u8
}

